#nullable enable // autogenerated

using MVZ2Logic;
using MVZ2Logic.Models;
using PVZEngine;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class MonsterSpawnerModel : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            base.UpdateFrame(deltaTime);
            var currentID = Model.GetProperty<NamespaceID>("EntityToSpawn");
            if (entityID != currentID)
            {
                entityID = currentID;

                if (Global.Resources != null)
                {
                    var sprite = Global.Resources.GetDefaultSprite();
                    var def = Global.Game.GetEntityDefinition(entityID);
                    if (def != null)
                    {
                        var modelID = def.GetModelID();
                        sprite = Global.Resources.GetModelIcon(modelID);
                    }
                    iconRenderer.sprite = sprite;
                }
            }
        }
        [SerializeField]
        private SpriteRenderer iconRenderer = null!;
        private NamespaceID? entityID;
    }
}
